import nodemailer from 'nodemailer';
import { z } from 'zod';

export const contactSchema = z.strictObject({
  name: z.string().trim().min(1).max(120),
  email: z.email().max(254),
  subject: z.string().trim().min(1).max(160).refine(value => !value.includes('\r') && !value.includes('\n')),
  message: z.string().trim().min(1).max(5000),
  website: z.string().max(500).optional(),
});

/** Creates bounded SMTP delivery; visitor input cannot choose recipients or the envelope sender. */
export function createContactMailer(settings = process.env) {
  const ready = Boolean(settings.SMTP_HOST && settings.SMTP_FROM && settings.CONTACT_TO);
  let transport;
  if (ready) {
    const port = Number(settings.SMTP_PORT || 587);
    if (!Number.isInteger(port) || port < 1 || port > 65535) throw new Error('SMTP_PORT must be a valid port.');
    const sender = settings.SMTP_FROM.match(/^[^<>\r\n]*<([^<>\s]+)>$/)?.[1] ?? settings.SMTP_FROM;
    if (!z.email().safeParse(sender).success) throw new Error('SMTP_FROM must be an email address or "Name <email@domain>".');
    z.email().parse(settings.CONTACT_TO);
    if (Boolean(settings.SMTP_USER) !== Boolean(settings.SMTP_PASSWORD)) throw new Error('Configure both SMTP_USER and SMTP_PASSWORD.');
    transport = nodemailer.createTransport({
      host: settings.SMTP_HOST, port,
      secure: settings.SMTP_SECURE === 'true', requireTLS: settings.SMTP_SECURE !== 'true',
      ...(settings.SMTP_USER ? { auth: { user: settings.SMTP_USER, pass: settings.SMTP_PASSWORD } } : {}),
      connectionTimeout: 10000, greetingTimeout: 10000, socketTimeout: 15000,
      disableFileAccess: true, disableUrlAccess: true,
    });
  }
  return {
    ready,
    /** Sends plain text with fixed addressing and an explicitly validated Reply-To address. */
    async send(content) {
      const result = await transport.sendMail({
        from: settings.SMTP_FROM, to: settings.CONTACT_TO, replyTo: content.email,
        subject: `[WISE Contact] ${content.subject}`,
        text: `Name: ${content.name}\nEmail: ${content.email}\n\n${content.message}`,
      });
      if (!result.accepted?.length) throw new Error('SMTP did not accept the message.');
    },
    /** Releases any SMTP transport resources during API shutdown. */
    close() { transport?.close(); },
  };
}